from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

if __package__ in {None, ""}:
    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from freesolo.contracts.markdown import (
    load_contract_spec,
    load_contract_text,
)
from freesolo.contracts.types import ContractSpec
from freesolo.datasets.records import load_task_examples
from freesolo.utils.core import (
    ValidationResult,
    _maybe_parse_json_text,
    json_safe_value,
    load_dotenv_if_available,
    load_json_schema,
    serialize_value,
    split_name,
    validate_output,
    write_jsonl,
)
from freesolo.utils.openai import (
    DEFAULT_OPENAI_ORACLE_MODEL,
    OPENAI_CHAT_COMPLETIONS_BATCH_ENDPOINT,
    build_openai_chat_payload,
    create_openai_batch,
    download_openai_file_text,
    extract_openai_message_content,
    generate_openai_text,
    iter_jsonl_objects,
    resolve_openai_model,
    upload_openai_batch_file,
    wait_for_openai_batch,
)

DEFAULT_MODEL = DEFAULT_OPENAI_ORACLE_MODEL
DEFAULT_BATCH_POLL_INTERVAL_SECONDS = 30.0
DEFAULT_BATCH_TIMEOUT_SECONDS = 24 * 60 * 60


def build_ground_truth_record(
    *,
    source_record: dict[str, Any],
    task_text: str,
    raw_output: Any,
    validation: ValidationResult,
    provider: str,
    model: str,
    metadata: dict[str, Any],
    source_path: str,
    source_index: int,
) -> dict[str, Any]:
    parsed_output = getattr(validation, "parsed", raw_output)
    validation_metadata = {
        "ok": bool(getattr(validation, "ok", True)),
        "checks": dict(getattr(validation, "checks", {}) or {}),
        "errors": list(getattr(validation, "errors", []) or []),
    }
    return {
        "id": _source_record_id(source_record, source_index),
        "input": task_text,
        "raw_output": serialize_value(raw_output),
        "output": parsed_output,
        "validation": validation_metadata,
        "split": split_name(task_text),
        "oracle_provider": provider,
        "oracle_model": model,
        "oracle_attempts": 1,
        "provider": provider,
        "model": model,
        "metadata": {
            **metadata,
            "source_index": source_index,
            "source_path": source_path,
        },
    }


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Generate ground-truth JSONL samples.")
    parser.add_argument("--contract", default="TRAINING_CONTRACT.md")
    parser.add_argument("--input", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--schema")
    parser.add_argument("--environment")
    parser.add_argument(
        "--model",
        default=DEFAULT_MODEL,
        help="OpenAI model id.",
    )
    parser.add_argument("--max-tokens", type=int, required=True)
    parser.add_argument("--limit", type=int, default=0)
    parser.add_argument("--use-batch", action="store_true")
    return parser.parse_args()


def _call_openai(
    *,
    model: str,
    system_prompt: str | None,
    messages: list[dict[str, str]],
    schema: dict[str, Any] | None,
    max_tokens: int,
) -> Any:
    provider_messages = list(messages)
    if system_prompt:
        provider_messages = [
            {"role": "system", "content": system_prompt},
            *provider_messages,
        ]

    response_format = _response_format(schema)
    content = generate_openai_text(
        model=model,
        messages=provider_messages,
        max_tokens=max_tokens,
        response_format=response_format,
        timeout_seconds=120.0,
    )
    return _maybe_parse_json_text(content)


def _response_format(schema: dict[str, Any] | None) -> dict[str, Any]:
    if schema is None:
        return {"type": "json_object"}
    return {
        "type": "json_schema",
        "json_schema": {
            "name": "output",
            "schema": schema,
        },
    }


def _batch_custom_id(index: int) -> str:
    return f"freesolo-oracle-{index:06d}"


def generate_ground_truth_records(
    *,
    input_path: str | Path,
    max_tokens: int,
    contract_path: str | Path = "TRAINING_CONTRACT.md",
    output_path: str | Path | None = None,
    schema_path: str | Path | None = None,
    environment: str | None = None,
    model: str = DEFAULT_MODEL,
    limit: int = 0,
    use_batch: bool = False,
) -> list[dict[str, Any]]:
    from freesolo.environments.base import load_environment

    load_dotenv_if_available()
    model = resolve_openai_model(model)

    contract_text = load_contract_text(contract_path)
    contract_spec = load_contract_spec(contract_path)
    schema = load_json_schema(schema_path)
    training_environment = load_environment(
        environment,
        contract_path=str(contract_path),
        dataset_path=str(input_path),
        mode="oracle",
    )
    examples = load_task_examples(input_path)
    if limit > 0:
        examples = examples[:limit]

    if use_batch:
        output_records = _generate_ground_truth_records_batch(
            examples=examples,
            contract_text=contract_text,
            contract_spec=contract_spec,
            training_environment=training_environment,
            schema=schema,
            model=model,
            max_tokens=max_tokens,
            input_path=input_path,
            output_path=output_path,
        )
    else:
        output_records = _generate_ground_truth_records_sync(
            examples=examples,
            contract_text=contract_text,
            contract_spec=contract_spec,
            training_environment=training_environment,
            schema=schema,
            model=model,
            max_tokens=max_tokens,
            input_path=input_path,
        )

    if output_path is not None:
        write_jsonl(output_path, output_records)
    return output_records


def _generate_ground_truth_records_sync(
    *,
    examples: list[Any],
    contract_text: str,
    contract_spec: ContractSpec | None,
    training_environment: Any,
    schema: dict[str, Any] | None,
    model: str,
    max_tokens: int,
    input_path: str | Path,
) -> list[dict[str, Any]]:
    output_records: list[dict[str, Any]] = []
    for index, example in enumerate(examples):
        oracle_messages = training_environment.build_oracle_messages(
            example,
            contract_text,
            contract_spec=contract_spec,
        )
        system_prompt, provider_messages = _split_messages(oracle_messages)
        ground_truth = _call_openai(
            model=model,
            system_prompt=system_prompt,
            messages=provider_messages,
            schema=schema,
            max_tokens=max_tokens,
        )
        validation = validate_output(
            ground_truth,
            schema=schema,
            require_json=bool(schema),
        )
        output_records.append(
            build_ground_truth_record(
                source_record=example.record,
                task_text=example.input,
                raw_output=ground_truth,
                validation=validation,
                provider="openai",
                model=model,
                metadata=example.metadata,
                source_path=str(Path(input_path)),
                source_index=index,
            )
        )
    return output_records


def _generate_ground_truth_records_batch(
    *,
    examples: list[Any],
    contract_text: str,
    contract_spec: ContractSpec | None,
    training_environment: Any,
    schema: dict[str, Any] | None,
    model: str,
    max_tokens: int,
    input_path: str | Path,
    output_path: str | Path | None,
) -> list[dict[str, Any]]:
    if not examples:
        return []

    response_format = _response_format(schema)
    requests: list[dict[str, Any]] = []
    for index, example in enumerate(examples):
        oracle_messages = training_environment.build_oracle_messages(
            example,
            contract_text,
            contract_spec=contract_spec,
        )
        system_prompt, provider_messages = _split_messages(oracle_messages)
        if system_prompt:
            provider_messages = [
                {"role": "system", "content": system_prompt},
                *provider_messages,
            ]
        requests.append(
            {
                "custom_id": _batch_custom_id(index),
                "method": "POST",
                "url": OPENAI_CHAT_COMPLETIONS_BATCH_ENDPOINT,
                "body": build_openai_chat_payload(
                    model=model,
                    messages=provider_messages,
                    max_tokens=max_tokens,
                    response_format=response_format,
                ),
            }
        )

    jsonl_text = (
        "\n".join(json.dumps(item, ensure_ascii=False) for item in requests) + "\n"
    )
    input_file = upload_openai_batch_file(
        jsonl_text=jsonl_text,
    )
    batch = create_openai_batch(
        input_file_id=str(input_file["id"]),
    )
    completed_batch = wait_for_openai_batch(
        str(batch["id"]),
        poll_interval_seconds=DEFAULT_BATCH_POLL_INTERVAL_SECONDS,
        timeout_seconds=DEFAULT_BATCH_TIMEOUT_SECONDS,
    )
    batch_id = str(completed_batch["id"])
    input_file_id = str(input_file["id"])
    output_file_id = completed_batch.get("output_file_id")
    output_file_id = output_file_id.strip() if isinstance(output_file_id, str) else None
    error_file_id = completed_batch.get("error_file_id")
    error_file_id = error_file_id.strip() if isinstance(error_file_id, str) else None

    outputs_by_id: dict[str, dict[str, Any]] = {}
    failure_rows_by_id: dict[str, dict[str, Any]] = {}
    failure_errors_by_id: dict[str, Any] = {}
    if output_file_id:
        output_text = download_openai_file_text(output_file_id)
        for custom_id, row in _batch_rows_by_custom_id(output_text).items():
            response_body, error = _batch_response_body(row)
            if response_body is None:
                failure_rows_by_id[custom_id] = row
                failure_errors_by_id[custom_id] = error
                continue
            outputs_by_id[custom_id] = response_body

    if error_file_id:
        error_text = download_openai_file_text(error_file_id)
        for custom_id, row in _batch_rows_by_custom_id(error_text).items():
            if custom_id in outputs_by_id:
                continue
            _, error = _batch_response_body(row)
            failure_rows_by_id.setdefault(custom_id, row)
            failure_errors_by_id.setdefault(
                custom_id,
                error
                or {
                    "code": "error_file_row",
                    "message": "OpenAI batch error file included this row.",
                },
            )

    output_records: list[dict[str, Any]] = []
    failure_records: list[dict[str, Any]] = []
    for index, example in enumerate(examples):
        custom_id = _batch_custom_id(index)
        response_body = outputs_by_id.get(custom_id)
        if response_body is None:
            failure_records.append(
                _batch_failure_record(
                    example=example,
                    source_index=index,
                    custom_id=custom_id,
                    input_path=input_path,
                    batch_id=batch_id,
                    input_file_id=input_file_id,
                    output_file_id=output_file_id,
                    error_file_id=error_file_id,
                    batch_row=failure_rows_by_id.get(custom_id),
                    error=failure_errors_by_id.get(
                        custom_id,
                        {
                            "code": "missing_batch_result",
                            "message": (
                                "No output or error row was returned for this "
                                "OpenAI batch custom_id."
                            ),
                        },
                    ),
                )
            )
            continue
        try:
            ground_truth = _maybe_parse_json_text(
                extract_openai_message_content(response_body)
            )
            validation = validate_output(
                ground_truth,
                schema=schema,
                require_json=bool(schema),
            )
            output_records.append(
                build_ground_truth_record(
                    source_record=example.record,
                    task_text=example.input,
                    raw_output=ground_truth,
                    validation=validation,
                    provider="openai_batch",
                    model=model,
                    metadata={
                        **example.metadata,
                        "openai_batch_id": batch_id,
                        "openai_batch_input_file_id": input_file_id,
                        "openai_batch_output_file_id": output_file_id,
                        "openai_batch_custom_id": custom_id,
                    },
                    source_path=str(Path(input_path)),
                    source_index=index,
                )
            )
        except Exception as error:
            failure_records.append(
                _batch_failure_record(
                    example=example,
                    source_index=index,
                    custom_id=custom_id,
                    input_path=input_path,
                    batch_id=batch_id,
                    input_file_id=input_file_id,
                    output_file_id=output_file_id,
                    error_file_id=error_file_id,
                    batch_row=None,
                    error={
                        "code": "record_build_failed",
                        "message": str(error),
                        "type": type(error).__name__,
                    },
                )
            )

    if failure_records:
        if output_path is None:
            return output_records
        resolved_output_path = Path(output_path)
        failure_stem = (
            resolved_output_path.stem
            if resolved_output_path.suffix
            else resolved_output_path.name
        )
        failure_path = resolved_output_path.with_name(f"{failure_stem}.failures.jsonl")
        write_jsonl(resolved_output_path, output_records)
        write_jsonl(failure_path, failure_records)
        raise RuntimeError(
            f"OpenAI batch {batch_id} completed with {len(output_records)} "
            f"successful rows and {len(failure_records)} failed or missing "
            f"rows; wrote {len(output_records)} successful rows to "
            f"{resolved_output_path} and {len(failure_records)} failure rows "
            f"to {failure_path}"
        )
    return output_records


def _source_record_id(source_record: dict[str, Any], source_index: int) -> str:
    return str(
        source_record.get("id")
        or source_record.get("_id")
        or f"example_{source_index:06d}"
    )


def _batch_rows_by_custom_id(text: str) -> dict[str, dict[str, Any]]:
    rows: dict[str, dict[str, Any]] = {}
    for item in iter_jsonl_objects(text):
        custom_id = item.get("custom_id")
        if not isinstance(custom_id, str) or not custom_id:
            raise RuntimeError(f"OpenAI batch output row missing custom_id: {item}")
        if custom_id in rows:
            raise RuntimeError(
                f"OpenAI batch output contained duplicate custom_id: {custom_id}"
            )
        rows[custom_id] = item
    return rows


def _batch_response_body(
    item: dict[str, Any],
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    error = item.get("error")
    if error:
        return None, {
            "code": "openai_batch_row_error",
            "message": "OpenAI batch row included an error.",
            "detail": json_safe_value(error),
        }
    response = item.get("response")
    if not isinstance(response, dict):
        return None, {
            "code": "missing_response",
            "message": "OpenAI batch row did not include a response object.",
        }
    status_code = response.get("status_code")
    if isinstance(status_code, int) and status_code >= 400:
        return None, {
            "code": "response_status_error",
            "message": f"OpenAI batch row returned HTTP {status_code}.",
        }
    body = response.get("body")
    if not isinstance(body, dict):
        return None, {
            "code": "missing_response_body",
            "message": "OpenAI batch row response body was not an object.",
        }
    return body, None


def _batch_failure_record(
    *,
    example: Any,
    source_index: int,
    custom_id: str,
    input_path: str | Path,
    batch_id: str,
    input_file_id: str,
    output_file_id: str | None,
    error_file_id: str | None,
    batch_row: dict[str, Any] | None,
    error: Any,
) -> dict[str, Any]:
    response = batch_row.get("response") if isinstance(batch_row, dict) else None
    response_status_code = (
        response.get("status_code") if isinstance(response, dict) else None
    )
    response_body = response.get("body") if isinstance(response, dict) else None
    return {
        "source_id": _source_record_id(example.record, source_index),
        "source_index": source_index,
        "source_path": str(Path(input_path)),
        "input": example.input,
        "custom_id": custom_id,
        "openai_batch_id": batch_id,
        "openai_batch_input_file_id": input_file_id,
        "openai_batch_output_file_id": output_file_id,
        "openai_batch_error_file_id": error_file_id,
        "error": json_safe_value(error),
        "response_status_code": json_safe_value(response_status_code),
        "response_body": json_safe_value(response_body),
        "raw_batch_row": json_safe_value(batch_row) if batch_row is not None else None,
    }


def main() -> int:
    load_dotenv_if_available()
    args = _parse_args()
    generate_ground_truth_records(
        input_path=args.input,
        contract_path=args.contract,
        output_path=args.output,
        schema_path=args.schema,
        environment=args.environment,
        model=args.model,
        max_tokens=args.max_tokens,
        limit=args.limit,
        use_batch=args.use_batch,
    )
    return 0


def _split_messages(
    messages: list[dict[str, str]],
) -> tuple[str | None, list[dict[str, str]]]:
    system_parts: list[str] = []
    provider_messages: list[dict[str, str]] = []
    for message in messages:
        role = str(message.get("role", "user"))
        content = str(message.get("content", ""))
        if role == "system":
            system_parts.append(content)
            continue
        provider_messages.append({"role": role, "content": content})
    if not provider_messages:
        provider_messages.append({"role": "user", "content": ""})
    system_prompt = "\n\n".join(part for part in system_parts if part.strip()) or None
    return system_prompt, provider_messages


__all__ = [
    "generate_ground_truth_records",
]


if __name__ == "__main__":
    raise SystemExit(main())
